(function() {
    'use strict';

    class CapstoneCompeteAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Express Capstone COMPETE';
            this.version = '1.1.0';

            this.EXPANSION_COST = { andina: 8, sur: 10, norte: 12 };
            this.MARKET_SIZE = { central: 48000, andina: 12000, sur: 9000, norte: 22000 };
            this.MARKET_GROWTH = { central: 0.012, andina: 0.015, sur: 0.009, norte: 0.01 };

            this.QUARTERS = [
                {
                    en: 'Q1: The board expects a clear strategic vision. Mercado Central is stable with moderate growth. Competitor A holds 18% share and is investing in digital marketing. Your brand has solid recognition but innovation pipeline needs investment.',
                    es: 'T1: La junta espera una clara estrategia. Mercado Central se mantiene estable con crecimiento moderado. El Competidor A tiene 18% de mercado e invierte en marketing digital. Su marca tiene buen reconocimiento pero la cartera de productos necesita mayor desarrollo.'
                },
                {
                    en: 'Q2: Consumer confidence is rising across the region. Market growth accelerates by +1% this quarter. Competitor B has launched a premium organic product line that is gaining traction with younger consumers.',
                    es: 'T2: La confianza del consumidor aumenta en la region. El crecimiento del mercado se acelera +1% este trimestre. El Competidor B ha lanzado una linea de productos organicos premium que gana terreno entre consumidores jovenes.'
                },
                {
                    en: 'Q3: REGULATORY ALERT - A new sugar tax of 8% has been announced in Mercado Central, effective immediately. Your COGS will increase by approximately 3%. Consider reformulating products or absorbing the cost impact. Competitors face the same pressure.',
                    es: 'T3: ALERTA REGULATORIA - Se ha anunciado un nuevo impuesto al azucar del 8% en Mercado Central, efectivo de inmediato. Su costo de ventas aumentara aproximadamente 3%. Considere reformular productos o absorber el impacto. Los competidores enfrentan la misma presion.'
                },
                {
                    en: 'Q4: Competitor A has aggressively cut prices by 7% in the value segment to defend market share. Traditional trade channels are showing signs of consolidation. E-commerce penetration continues to grow at 25% year-over-year.',
                    es: 'T4: El Competidor A ha reducido precios agresivamente un 7% en el segmento de valor para defender participacion. Los canales de comercio tradicional muestran signos de consolidacion. El comercio electronico sigue creciendo al 25% interanual.'
                },
                {
                    en: 'Q5: SUPPLY CHAIN DISRUPTION - A major port strike has disrupted raw material imports. Production capacity is reduced by 15% this quarter unless you invested heavily in capacity last quarter. Alternative sourcing adds +5% to COGS.',
                    es: 'T5: INTERRUPCION DE CADENA DE SUMINISTRO - Una huelga portuaria importante ha interrumpido las importaciones. La capacidad de produccion se reduce un 15% este trimestre a menos que haya invertido en capacidad el trimestre anterior. Fuentes alternativas agregan +5% al costo de ventas.'
                },
                {
                    en: 'Q6: Economic boom across LATAM! All markets experience +2% additional growth this quarter. Consumer spending on premium products surges. This is an opportunity to capture share with innovation and brand investment.',
                    es: 'T6: Auge economico en LATAM! Todos los mercados experimentan +2% de crecimiento adicional este trimestre. El gasto del consumidor en productos premium aumenta. Es una oportunidad para capturar mercado con innovacion e inversion en marca.'
                },
                {
                    en: 'Q7: CURRENCY SHOCK - The local currency has devalued 12% against the US dollar. Import costs increase by 5%. Companies with strong local supply chains are less affected. Export opportunities to dollarized markets improve.',
                    es: 'T7: CHOQUE CAMBIARIO - La moneda local se ha devaluado un 12% frente al dolar. Los costos de importacion aumentan un 5%. Las empresas con fuertes cadenas de suministro locales se ven menos afectadas. Las oportunidades de exportacion a mercados dolarizados mejoran.'
                },
                {
                    en: 'Q8: Competitor C has initiated an aggressive price war in Mercado Central, cutting prices by 12%. Market analysts expect this will erode industry margins. Your sales team reports pressure from key retailers to match pricing.',
                    es: 'T8: El Competidor C ha iniciado una guerra de precios agresiva en Mercado Central, reduciendo precios un 12%. Los analistas esperan que esto erosione margenes de la industria. Su equipo de ventas reporta presion de retailers clave para igualar precios.'
                },
                {
                    en: 'Q9: NEW REGULATION - Sustainability disclosure requirements are now mandatory. Companies must invest in ESG reporting and sustainable packaging. Estimated compliance cost: $2M per quarter. Non-compliance results in a $5M fine and brand damage.',
                    es: 'T9: NUEVA REGULACION - Los requisitos de divulgacion de sostenibilidad ahora son obligatorios. Las empresas deben invertir en reportes ESG y empaques sostenibles. Costo de cumplimiento estimado: $2M por trimestre. El incumplimiento genera una multa de $5M y perdida de marca.'
                },
                {
                    en: 'Q10: A new regional trade agreement reduces tariffs between LATAM markets by 15%. This significantly lowers the cost of international expansion. Companies with multi-market presence benefit most from supply chain optimization.',
                    es: 'T10: Un nuevo acuerdo comercial regional reduce aranceles entre mercados LATAM en un 15%. Esto reduce significativamente el costo de expansion internacional. Las empresas con presencia multimercado se benefician mas de la optimizacion de la cadena de suministro.'
                },
                {
                    en: 'Q11: RECESSION WARNING - Economic indicators signal a slowdown. Consumer spending is expected to decline by 3% next quarter. Retailers are cutting inventory orders. Defensive positioning and cash preservation become critical.',
                    es: 'T11: ALERTA DE RECESION - Los indicadores economicos senalan una desaceleracion. Se espera que el gasto del consumidor disminuya un 3% el proximo trimestre. Los retailers estan reduciendo pedidos de inventario. La posicion defensiva y la preservacion de efectivo son criticas.'
                },
                {
                    en: 'Q12: FINAL QUARTER - The board will evaluate your 3-year performance. Focus on delivering strong final-quarter results while positioning the company for long-term value creation. Shareholder expectations are high.',
                    es: 'T12: TRIMESTRE FINAL - La junta evaluara su desempeno de 3 anos. Enfoquese en entregar resultados solidos este trimestre mientras posiciona la empresa para creacion de valor a largo plazo. Las expectativas de los accionistas son altas.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 28,
                    debt: 80,
                    equity: 185,
                    baseRevenue: 121,
                    marketShareCentral: 9.5,
                    brandEquity: 50,
                    innovationScore: 40,
                    capacity: 120000,
                    salesForce: 450,
                    workforce: 1850,
                    totalCapex: 0,
                    marketsEntered: [],
                    marketQuarters: {},
                    cumulativeNetIncome: 0,
                    sharesOutstanding: 10,
                    peMultiple: 15,
                    sugarTaxActive: false,
                    sustainabilityCompliant: false,
                    revenueHistory: [],
                    shareHistory: [],
                    netIncomeHistory: [],
                    epsHistory: [],
                    sharePriceHistory: [],
                    ebitdaHistory: [],
                    lastEventMsg: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    priceIndex: 100,
                    marketingBudget: 15,
                    rdBudget: 8,
                    salesChange: 0,
                    capexInvestment: 0,
                    expansionTarget: 'none',
                    dividendRate: 20
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var pi = document.getElementById('priceInput');
            if (pi) decisions.priceIndex = parseInt(pi.value);
            var mi = document.getElementById('marketingInput');
            if (mi) decisions.marketingBudget = parseFloat(mi.value);
            var ri = document.getElementById('rdInput');
            if (ri) decisions.rdBudget = parseFloat(ri.value);
            var si = document.getElementById('salesInput');
            if (si) decisions.salesChange = parseInt(si.value);
            var ci = document.getElementById('capexInput');
            if (ci) decisions.capexInvestment = parseFloat(ci.value);
            var ei = document.getElementById('expansionInput');
            if (ei) decisions.expansionTarget = ei.value;
            var di = document.getElementById('dividendInput');
            if (di) decisions.dividendRate = parseFloat(di.value);

            if (!decisions.priceIndex || decisions.priceIndex < 80 || decisions.priceIndex > 120) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('price_warning'), 'warning'
                );
                return false;
            }
            if (decisions.marketingBudget < 5 || decisions.marketingBudget > 50) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('marketing_warning'), 'warning'
                );
                return false;
            }
            if (decisions.rdBudget < 0 || decisions.rdBudget > 30) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('rd_warning'), 'warning'
                );
                return false;
            }
            if (decisions.dividendRate < 0 || decisions.dividendRate > 50) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('dividend_warning'), 'warning'
                );
                return false;
            }

            var ds = window.mySimulation.state.domainState;
            if (decisions.expansionTarget !== 'none' && ds.marketsEntered.indexOf(decisions.expansionTarget) !== -1) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('market_already_entered'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var q = state.currentPeriod;
            var eventMsg = '';

            // --- Update strategic assets ---
            ds.brandEquity += (d.marketingBudget - 15) * 0.25;
            ds.brandEquity = Math.max(10, Math.min(100, ds.brandEquity));

            ds.innovationScore += (d.rdBudget - 8) * 0.35;
            ds.innovationScore = Math.max(5, Math.min(100, ds.innovationScore));

            ds.salesForce += d.salesChange;
            ds.salesForce = Math.max(100, Math.min(1200, ds.salesForce));
            ds.workforce += d.salesChange;

            ds.capacity += Math.round(d.capexInvestment * 800);
            ds.totalCapex += d.capexInvestment;

            // --- Market expansion ---
            var expansionCost = 0;
            if (d.expansionTarget !== 'none' && ds.marketsEntered.indexOf(d.expansionTarget) === -1) {
                expansionCost = this.EXPANSION_COST[d.expansionTarget] || 0;
                if (q >= 10) {
                    expansionCost = Math.round(expansionCost * 0.85);
                    eventMsg += '<br>' + window.mySimulation.t('ev_trade');
                }
                ds.marketsEntered.push(d.expansionTarget);
                ds.marketQuarters[d.expansionTarget] = q;
            }

            // --- Event effects ---
            var cogsAdjust = 0;
            var demandAdjust = 0;
            var capacityPenalty = 1.0;
            var extraCost = 0;

            if (q === 3) {
                ds.sugarTaxActive = true;
                cogsAdjust += 0.03;
                eventMsg += '<br>' + window.mySimulation.t('ev_sugar');
            }
            if (ds.sugarTaxActive && q > 3) {
                cogsAdjust += 0.03;
            }

            if (q === 5) {
                if (d.capexInvestment < 10) {
                    capacityPenalty = 0.85;
                    eventMsg += '<br>' + window.mySimulation.t('ev_port_hit');
                } else {
                    eventMsg += '<br>' + window.mySimulation.t('ev_port_ok');
                }
                cogsAdjust += 0.05;
                eventMsg += '<br>' + window.mySimulation.t('ev_altsource');
            }

            if (q === 2 || q === 6) {
                demandAdjust += 0.02;
                eventMsg += '<br>' + window.mySimulation.t('ev_growth');
            }

            if (q === 7) {
                cogsAdjust += 0.05;
                eventMsg += '<br>' + window.mySimulation.t('ev_currency');
            }

            if (q === 8) {
                demandAdjust -= 0.015;
                eventMsg += '<br>' + window.mySimulation.t('ev_pricewar');
            }

            if (q >= 9) {
                if (d.marketingBudget >= 12) {
                    ds.sustainabilityCompliant = true;
                    extraCost += 2;
                    eventMsg += '<br>' + window.mySimulation.t('ev_sustain');
                } else {
                    if (!ds.sustainabilityCompliant) {
                        extraCost += 5;
                        ds.brandEquity -= 3;
                        eventMsg += '<br>' + window.mySimulation.t('ev_noncomp');
                    }
                }
            }

            if (q === 11) {
                demandAdjust -= 0.03;
                eventMsg += '<br>' + window.mySimulation.t('ev_recession');
            }

            // --- Demand calculation ---
            var priceMult = 1 + (100 - d.priceIndex) * 0.012;
            var brandMult = 0.7 + ds.brandEquity * 0.006;
            var salesMult = 0.8 + Math.min(ds.salesForce, 900) * 0.00035;
            var innovMult = 0.85 + ds.innovationScore * 0.003;

            var competitiveResponse = 1.0;
            if (ds.marketShareCentral > 12) {
                competitiveResponse = 1 - (ds.marketShareCentral - 12) * 0.015;
            }

            var demandFactor = priceMult * brandMult * salesMult * innovMult * competitiveResponse;
            demandFactor *= (1 + demandAdjust);
            demandFactor *= capacityPenalty;

            // --- Market growth ---
            var growthRate = this.MARKET_GROWTH['central'];
            ds.baseRevenue *= (1 + growthRate);

            // --- Revenue from home market ---
            var homeRevenue = ds.baseRevenue * demandFactor * (d.priceIndex / 100);

            // --- Revenue from entered markets ---
            var intlRevenue = 0;
            for (var m = 0; m < ds.marketsEntered.length; m++) {
                var mkt = ds.marketsEntered[m];
                var quartersIn = q - (ds.marketQuarters[mkt] || q);
                var mktSize = this.MARKET_SIZE[mkt] / 4;
                var mktPenetration = Math.min(0.06, 0.01 + quartersIn * 0.008);
                intlRevenue += mktSize * mktPenetration * (d.priceIndex / 100) * brandMult;
            }

            var totalRevenue = homeRevenue + intlRevenue;

            // --- Cost structure ---
            var baseCOGSratio = 0.55 + cogsAdjust;
            var cogs = totalRevenue * baseCOGSratio;
            var grossProfit = totalRevenue - cogs;

            var salesExpense = ds.salesForce * 0.02;
            var marketingExpense = d.marketingBudget;
            var rdExpense = d.rdBudget;
            var adminExpense = 5 + (ds.marketsEntered.length * 1.5);
            var totalOpex = salesExpense + marketingExpense + rdExpense + adminExpense + extraCost;

            var ebitda = grossProfit - totalOpex;
            var depreciation = 3 + ds.totalCapex * 0.015;
            var operatingIncome = ebitda - depreciation;

            var interestExpense = ds.debt * 0.055 / 4;
            var ebt = operatingIncome - interestExpense;
            var taxes = Math.max(0, ebt * 0.28);
            var netIncome = ebt - taxes;

            // --- Dividends and cash flow ---
            var dividends = 0;
            if (netIncome > 0) {
                dividends = netIncome * (d.dividendRate / 100);
            }

            var cashFlow = netIncome + depreciation - d.capexInvestment - expansionCost - dividends;
            ds.cash += cashFlow;

            // --- Auto-borrow if cash is negative ---
            if (ds.cash < 0) {
                var borrowAmount = Math.ceil(Math.abs(ds.cash) + 5);
                ds.debt += borrowAmount;
                ds.cash += borrowAmount;
                eventMsg += '<br>' + window.mySimulation.t('ev_borrow').replace('{n}', borrowAmount);
            }

            // --- Update equity ---
            ds.equity += (netIncome - dividends);
            ds.cumulativeNetIncome += netIncome;

            // --- Market share dynamics ---
            var shareShift = (demandFactor - 1) * 2.5;
            if (q === 8) shareShift -= 1.5;
            var noise = (Math.sin(q * 7.3 + d.priceIndex * 0.1) * 0.5);
            ds.marketShareCentral += shareShift + noise;
            ds.marketShareCentral = Math.max(3, Math.min(25, ds.marketShareCentral));

            // --- Valuation metrics ---
            var annualizedNI = netIncome * 4;
            var eps = annualizedNI / ds.sharesOutstanding;

            var growthFactor = 1;
            if (ds.revenueHistory.length > 0) {
                var prevRev = ds.revenueHistory[ds.revenueHistory.length - 1];
                if (prevRev > 0) {
                    growthFactor = totalRevenue / prevRev;
                }
            }
            ds.peMultiple = Math.max(8, Math.min(25, ds.peMultiple * (0.85 + growthFactor * 0.2)));
            if (netIncome < 0) ds.peMultiple *= 0.9;

            var sharePrice = Math.max(1, eps * ds.peMultiple);
            if (eps <= 0) sharePrice = Math.max(1, ds.equity / ds.sharesOutstanding * 0.5);

            var roe = ds.equity > 0 ? (annualizedNI / ds.equity * 100) : 0;
            var grossMargin = totalRevenue > 0 ? (grossProfit / totalRevenue * 100) : 0;
            var ebitdaMargin = totalRevenue > 0 ? (ebitda / totalRevenue * 100) : 0;
            var debtToEquity = ds.equity > 0 ? (ds.debt / ds.equity) : 999;

            // --- Push to history ---
            ds.revenueHistory.push(Math.round(totalRevenue * 10) / 10);
            ds.shareHistory.push(Math.round(ds.marketShareCentral * 10) / 10);
            ds.netIncomeHistory.push(Math.round(netIncome * 10) / 10);
            ds.epsHistory.push(Math.round(eps * 100) / 100);
            ds.sharePriceHistory.push(Math.round(sharePrice * 100) / 100);
            ds.ebitdaHistory.push(Math.round(ebitda * 10) / 10);
            ds.lastEventMsg = eventMsg;

            var results = {
                period: q,
                revenue: Math.round(totalRevenue * 10) / 10,
                cogs: Math.round(cogs * 10) / 10,
                grossProfit: Math.round(grossProfit * 10) / 10,
                grossMargin: Math.round(grossMargin * 10) / 10,
