        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.QUARTERS.length - 1);
            var quarter = this.QUARTERS[idx];
            var lang = 'en';
            try {
                var _sim = window.mySimulation;
                lang = (_sim && (_sim.language || _sim.currentLanguage)) || (typeof document !== 'undefined' && document.documentElement && document.documentElement.lang) || 'en';
            } catch(e) { lang = 'en'; }
            lang = ('' + lang).toLowerCase().slice(0, 2);
            if (lang === 'es' && quarter.es) {
                var briefEl = document.getElementById('briefingText');
                if (briefEl) briefEl.innerHTML = quarter.es;
            } else {
                var briefEl2 = document.getElementById('briefingText');
                if (briefEl2) briefEl2.innerHTML = quarter.en;
            }

            // Disable already-entered markets in dropdown
            var ds = state.domainState || {};
            var entered = ds.marketsEntered || [];
            var sel = document.getElementById('expansionInput');
            if (sel) {
                var opts = sel.options;
                for (var i = 0; i < opts.length; i++) {
                    var val = opts[i].value;
                    if (val !== 'none') {
                        opts[i].disabled = entered.indexOf(val) !== -1;
                        if (opts[i].disabled && sel.value === val) {
                            sel.value = 'none';
                        }
                    }
                }
            }
        }
